import sys

def is_good(a, points):
    """Check if point a (0-indexed) is good"""
    n = len(points)
    # Get all points from a's perspective
    vectors = [(points[i] - a) for i in range(n) if i != a]
    # Check all pairs of vectors
    for i in range(len(vectors)):
        for j in range(i + 1, len(vectors)):
            dot = sum(vectors[i][k] * vectors[j][k] for k in range(5))
            if dot > 0:
                return False
    return True

n = int(sys.stdin.readline())
points = []
for i in range(n):
    coords = list(map(int, sys.stdin.readline().split()))
    points.append(coords)

# Check each point
good_points = []
for idx in range(n):
    if is_good(points[idx], points):
        good_points.append(idx + 1)  # 1-indexed

# Output
print(len(good_points))
for p in good_points:
    print(p)
"}

