import sys
import math

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    a = [int(next(it)) for _ in range(n)]

    cnt_ones = sum(1 for x in a if x == 1)
    if cnt_ones:
        print(n - cnt_ones)
        return

    if n == 1:
        print(-1)
        return

    min_len = float('inf')
    for i in range(n):
        prefix_gcd = a[i]
        for j in range(i, n):
            prefix_gcd = math.gcd(prefix_gcd, a[j])
            if prefix_gcd == 1:
                min_len = min(min_len, j - i + 1)
                break

    if min_len == float('inf'):
        print(-1)
    else:
        print(min_len - 1 + (n - 1))

if __name__ == '__main__':
    solve()
"}

