def solve():
    n, q = map(int, input().split())
    a = list(map(int, input().split()))

    # Initialize Union-Find
    parent = list(range(n))

    def find(u):
        while parent[u] != u:
            parent[u] = parent[parent[u]]
            u = parent[u]
        return u

    def union(u, v):
        pu, pv = find(u), find(v)
        if pu != pv:
            parent[pu] = pv

    # For each bit position, connect all indices with that bit set
    for bit in range(31):  # since a[i] <= 300000, we need only 18 bits, but 31 is safe
        indices = [i for i in range(n) if (a[i] >> bit) & 1]
        if len(indices) >= 2:
            # Use the first index as the representative
            rep = indices[0]
            for i in indices[1:]:
                union(rep, i)

    # Answer queries
    for _ in range(q):
        x, y = map(int, input().split())
        if find(x - 1) == find(y - 1):
            print("Shi")
        else:
            print("Fou")

solve()
