    placed = False

    if tile == '0':  # vertical tile (2x1)
        for r in range(1, 4):  # rows 1 to 3
            for c in range(1, 5):  # columns 1 to 4
                # Check if this position is valid
                # Check if we can place vertically at (r, c)
                can_place = True
                for cr in range(r, r + 2):
                    for cc in range(c, c + 1):  # since it's vertical, c doesn't change
                        if (cr, cc) in occupied_cells:
                            can_place = False
                            break
                    if not can_place:
                        break

                if can_place:
                    # Place the tile
                    occupied_cells.add((r, c))
                    occupied_cells.add((r + 1, c))

                    # Check if any row or column becomes fully occupied
                    full_rows = []
                    full_columns = []

                    for row in range(1, 5):
                        if all((row, col) in occupied_cells for col in range(1, 5)):
                            full_rows.append(row)

                    for col in range(1, 5):
                        if all((row, col) in occupied_cells for row in range(1, 5)):
