def solve():
    n = int(input())

    # Check if n is prime
    def is_prime(num):
        if num < 2:
            return False
        if num == 2:
            return True
        if num % 2 == 0:
            return False
        for i in range(3, int(num**0.5) + 1, 2):
            if num % i == 0:
                return False
        return True

    if is_prime(n):
        print("NO")
        return

    # If n is composite, try to find a solution
    print("YES")
    print(1)  # k = 1

    # Use the largest proper divisor of n as b
    # The largest proper divisor is n//2 if n is even, or something else
    if n % 2 == 0:
        b = n // 2
        a = 1
    else:
        # Find the largest proper divisor of an odd composite number
        # Start from sqrt(n) and go down
        sqrt_n = int(n**0.5)
        for i in range(sqrt_n, 1, -1):
            if n % i == 0 and i != 1 and i != n:
                b = i
                a = 1
                break

    print(a, b)

solve()
