    if y1 == y2:  # horizontal segment
        # Row y1, columns from min(x1, x2) to max(x1, x2)
        y = y1
        x_start = min(x1, x2)
        x_end = max(x1, x2)

        if y in rows:
            rows[y].append((x_start, x_end))
        else:
            rows[y] = [(x_start, x_end)]
    else:  # vertical segment
        # Column x1, rows from min(y1, y2) to max(y1, y2)
        x = x1
        y_start = min(y1, y2)
        y_end = max(y1, y2)

        if x in cols:
