def can_form(a, k):
    """Check if we can form array a using powers of k."""

    # Greedy approach: for each position, subtract the largest power of k
    for i in range(len(a)):
        power = 0
        while k ** power <= a[i]:
            power += 1
        power -= 1

        # Subtract the largest power
        a[i] -= k ** power

    # After processing, all values should be zero
    return all(val == 0 for val in a)

T = int(input())
for _ in range(T):
    n, k = map(int, input().split())
    a = list(map(int, input().split()))

    # Check if we can form the array
    if can_form(a, k):
        print("YES")
    else:
        print("NO")
"}

