def find_parent(p, k):
    mid = 1 << (k - 1)
    depth = 0

    while True:
        power = 1 << (k - depth - 1)
        left_bound = 1 << (k - depth)
        right_bound = (3 << (k - depth - 1)) - 1

        if p == left_bound:
            return p + power
        elif p == right_bound:
            return p - power
        elif left_bound < p < right_bound:
            if p < mid:
                return p + power
            else:
                return p - power
        elif p == mid:
            return None
        else:
            depth += 1

n, q = map(int, input().split())
k = (n + 1).bit_length() - 1
mid = 1 << (k - 1)

for _ in range(q):
    u = int(input())
    path = input().strip()

    current = u
    for move in path:
        if move == 'L':
            # left child: exists if current is not a leaf and current > mid
            parent = find_parent(current, k)
            if parent is None:
                # current is root, left child exists
                left_child = mid
                current = left_child
            else:
                # current is not root
                depth = find_depth(current, k)
                power = 1 << (k - depth - 1)
                # current > mid means it's in the right subtree
                # left child = current - power
                left_child = current - power
                current = left_child
        elif move == 'R':
            # right child: exists if current is not a leaf and current < mid
            parent = find_parent(current, k)
            if parent is None:
                # current is root, right child exists
                right_child = (mid + 1) if mid + 1 <= n else None
                if right_child is not None:
