                power = 1 << (k - depth - 1)
                # current < mid means it's in the left subtree
                # right child = current + power
                right_child = current + power
                current = right_child
        elif move == 'U':
            # parent
            parent = find_parent(current, k)
            if parent is not None:
                current = parent

    print(current)
