import sys

def solve():
    data = sys.stdin.read().split()
    if not data:
        return
    it = iter(data)
    q = int(next(it))
    out_lines = []

    for _ in range(q):
        n = int(next(it))
        boards = []

        for _ in range(n):
            a = int(next(it))
            b = int(next(it))
            boards.append((a, b))

        # dp[i] = (height, cost) where i is the number of boards processed
        # dp[0] = (0, 0) means we haven't processed any boards yet
        dp = [(0, 0)]

        for a, b in boards:
            new_dp = []
            for prev_h, prev_cost in dp:
                # Try all possible heights for current board
                for curr_h in range(a, a + 3):
                    curr_cost = prev_cost + (curr_h - a) * b
                    if prev_h != curr_h:
                        new_dp.append((curr_h, curr_cost))

            # Find minimum cost for each possible height
            min_cost = {h: float('inf') for h in range(a, a + 3)}
            for curr_h, curr_cost in new_dp:
                min_cost[curr_h] = min(min_cost[curr_h], curr_cost)

            # Update dp with the minimum costs
            dp = [(h, min_cost[h]) for h in range(a, a + 3)]

        out_lines.append(str(dp[0][1]))

    sys.stdout.write("\n".join(out_lines))

if __name__ == "__main__":
    solve()
