def solve():
    n, m = map(int, input().split())

    # Build adjacency list
    adj = [[] for _ in range(n)]
    edges = []
    for _ in range(m):
        v, u, c = input().split()
        v = int(v) - 1
        u = int(u) - 1
        adj[v].append((u, c))
        edges.append((v, u, c))

    # Topologically sort
    in_degree = [0] * n
    for v, u, c in edges:
        in_degree[u] += 1

    topological_order = []
    for i in range(n):
        if in_degree[i] == 0:
            topological_order.append(i)

    # Process vertices in reverse topological order
    dp = [[False] * 26 for _ in range(n)]  # dp[v][c] means vertex v can win with minimum character c

    for v in reversed(topological_order):
        for c in range(26):
            # Check all outgoing edges from v
            for u, c_char in adj[v]:
                if ord(c_char) - ord('a') >= c:
                    # This move is valid
                    # Check if position (u, c) is losing for opponent
                    if not dp[u][c]:
                        dp[v][c] = True
                        break

    # Print results
    for i in range(n):
        row = []
        for j in range(n):
            # Max starts at i, Lucas at j
            # Max's first move has no constraint
            for c in range(26):
                if dp[i][c]:
                    row.append('A')
                    break
        print(''.join(row))

