def solve_game(n, m, edges):
    from collections import defaultdict, deque

    # Build adjacency list with ASCII values
    graph = defaultdict(list)
    for v, u, c in edges:
        graph[v].append((u, ord(c) - ord('a')))  # Map 'a'-'z' to 0-25

    # Find topological order using Kahn's algorithm
    in_degree = [0] * (n + 1)
    for v in range(1, n + 1):
        for u, _ in graph[v]:
            in_degree[u] += 1

    queue = deque()
    for v in range(1, n + 1):
        if in_degree[v] == 0:
            queue.append(v)

    topo_order = []
    while queue:
        v = queue.popleft()
        topo_order.append(v)
        for u, _ in graph[v]:
            in_degree[u] -= 1
            if in_degree[u] == 0:
                queue.append(u)

