        top_order.append(u)
        for v, _ in graph[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                queue.append(v)

    # DP table: dp[i][j] = (is_winning_position, last_char_used)
    # where is_winning_position = True if Max can force a win
    # and last_char_used is the character of the previous move

