q = int(input())
for _ in range(q):
    n = int(input())
    a = []
    b = []
    for _ in range(n):
        ai, bi = map(int, input().split())
        a.append(ai)
        b.append(bi)

    if n == 1:
        print(0)
        continue

    # dp[i][h] = min cost to make first i boards great with i-th board at height h
    # Use a dictionary for efficiency
    prev_heights = {a[0]: 0}

    for i in range(1, n):
        curr_heights = {}
        ai = a[i]
        bi = b[i]

        # Option 1: keep the i-th board at its original height
        if ai not in curr_heights:
            min_cost = float('inf')
            for h in prev_heights:
                if h != ai:
                    min_cost = min(min_cost, prev_heights[h])
            if min_cost != float('inf'):
                curr_heights[ai] = min_cost

        # Option 2: increase the i-th board to some height > ai
        for h in range(ai + 1, ai + 200):  # Check only up to 200 units above original height
            if h != a[i-1]:  # ensure h != a_{i-1}
                cost = prev_heights[a[i-1]] + (h - ai) * bi
                curr_heights[h] = min(curr_heights.get(h, float('inf')), cost)

        # Since we only need to consider the next board's original height, we should
        # only check heights that are either the next board's original height or just above it
        next_height = a[i+1] if i+1 < n else float('inf')
        for h in range(min(next_height, ai + 200), next_height + 200):
            if h != a[i-1]:
                cost = prev_heights[a[i-1]] + (h - ai) * bi
                curr_heights[h] = min(curr_heights.get(h, float('inf')), cost)

        prev_heights = curr_heights

    print(min(prev_heights.values()))
