def can_achieve(n, k, a):
    used = set()

    for num in a:
        # Find largest power of k <= num
        power = 0
        while k ** power <= num:
            power += 1
        power -= 1

        # Try to decompose num
        current = num
        while current > 0 and power >= 0:
            if k ** power <= current and k ** power not in used:
                used.add(k ** power)
                current -= k ** power
                power -= 1
            else:
                power -= 1

        if current > 0:
            return False

    return True

