def is_good(a, points):
    """Check if point a is good"""
    n = len(points)
    for i in range(n):
        if i == a:
            continue
        for j in range(n):
            if j == a or j == i:
                continue
            # Vector ab = b - a
            # Vector ac = c - a
            # Calculate dot product (b - a) · (c - a)
            dot = (points[i][0] - points[a][0]) * (points[j][0] - points[a][0]) +
                  (points[i][1] - points[a][1]) * (points[j][1] - points[a][1]) +
                  (points[i][2] - points[a][2]) * (points[j][2] - points[a][2]) +
                  (points[i][3] - points[a][3]) * (points[j][3] - points[a][3]) +
                  (points[i][4] - points[a][4]) * (points[j][4] - points[a][4])
            if dot > 0:
                return False
    return True

n = int(input())
