def longest_almost_constant_range(n, a):
    max_len = 1
    l = 0

    # Try all possible starting points
    for l in range(n):
        current_max = a[l]
        current_min = a[l]

        for r in range(l, n):
            # Expand window to the right
            if a[r] > current_max:
                current_max = a[r]
            elif a[r] < current_min:
                current_min = a[r]

            # Check if condition holds
            if current_max - current_min <= 1:
                max_len = max(max_len, r - l + 1)
            else:
                # Condition fails, break
                break

    return max_len

