def find_sequence(n):
    # Find all divisors of n
    divisors = set()
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            divisors.add(i)
            divisors.add(n // i)
    if not divisors:
        return "NO"

    # Check if n is prime
    is_prime = True
    for d in divisors:
        if d != n // d and d != n // d:
            is_prime = False
            break
    if is_prime:
        return "NO"

    # Construct the sequence
    sequence = []
    sum_so_far = 0

    # Try to use all divisors
    for d in sorted(divisors):
        # Calculate how much we need
        needed = (n - 1) - sum_so_far
        # We need a fraction a/d such that a/d <= needed
        max_a = min(d - 1, needed * d) // d
        sequence.append((max_a, d))
        sum_so_far += max_a / d

    # Check if we've reached the target
    if abs(sum_so_far - (n - 1) / n) < 1e-9:
        return f"YES\n{len(sequence)}\n" + "\n".join(f"{a} {b}" for a, b in sequence)
    else:
        return "NO"

n = int(input())
print(find_sequence(n))
