    # If n is prime, output NO
    if all(n % i != 0 for i in range(2, int(n**0.5) + 1)):
        return "NO"

    # Try using all proper divisors as denominators
    divisors = set()
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            divisors.add(i)
            divisors.add(n // i)

    if not divisors:
        return "NO"

    # Try to construct the sequence
    sequence = []
    remaining = (n - 1)

    # Try each divisor in decreasing order
    for b in sorted(divisors, reverse=True):
        a = min(b - 1, remaining)
        sequence.append((a, b))
        remaining -= a

    # Check if we've reached the target
    if remaining == 0:
        return f"YES\n{len(sequence)}\n" + "\n".join(f"{a} {b}" for a, b in sequence)
