def max_turtle_distance(commands: str, n: int) -> int:
    """Calculate the maximum distance the turtle can move from the starting point."""

    # dp[i][pos][dir][changes_used] = set of achievable positions at step i
    # We'll use a 4-dimensional DP array

    # Initialize: at step 0 (before any commands), position is 0, direction is +1
    # changes_used can be from 0 to n
    dp = [[[-1 for _ in range(n + 1)] for _ in range(2)] for _ in range(len(commands) + 1)]
    dp[0][0][0] = 0  # at step 0, position 0, direction 1, changes_used 0

    for i in range(len(commands)):
        for pos in range(i + 1):  # maximum position at step i is i
            for dir in range(2):  # 0 = -1, 1 = +1
                for changes_used in range(n + 1):
                    if dp[i][pos][dir][changes_used] == -1:
                        continue  # no state available

                    # Option 1: keep the current command
                    cmd = commands[i]

                    if cmd == 'F':
                        # move forward
                        if dir == 1:
                            new_pos = pos + 1
                        else:
                            new_pos = pos - 1

                        if new_pos >= 0 and new_pos <= i + 1:
                            dp[i + 1][new_pos][dir][changes_used] = max(dp[i + 1][new_pos][dir][changes_used], dp[i][pos][dir][changes_used])
                    else:  # cmd == 'T'
                        # turn around
                        new_dir = 1 if dir == 0 else 0

                        dp[i + 1][pos][new_dir][changes_used] = max(dp[i + 1][pos][new_dir][changes_used], dp[i][pos][dir][changes_used])

                    # Option 2: change the command (if changes_used < n)
                    if changes_used < n:
                        if cmd == 'F':
                            # change to 'T'
                            new_dir = 1 if dir == 0 else 0

                            dp[i + 1][pos][new_dir][changes_used + 1] = max(dp[i + 1][pos][new_dir][changes_used + 1],
                                                                          dp[i][pos][dir][changes_used])
                        else:  # cmd == 'T'
                            # change to 'F'
                            if dir == 1:
                                new_pos = pos + 1
                            else:
                                new_pos = pos - 1

                            if new_pos >= 0 and new_pos <= i + 1:
                                dp[i + 1][new_pos][dir][changes_used + 1] = max(dp[i + 1][new_pos][dir][changes_used + 1],
                                                                          dp[i][pos][dir][changes_used])

    # Find the maximum absolute distance at the end
    max_dist = 0
    for pos in range(len(commands) + 1):
        for dir in range(2):
            for changes_used in range(n + 1):
                if dp[len(commands)][pos][dir][changes_used] != -1:
                    max_dist = max(max_dist, abs(dp[len(commands)][pos][dir][changes_used]))

    return max_dist

# Read input and output result
import sys

if __name__ == "__main__":
    commands = sys.stdin.readline().strip()
    n = int(sys.stdin.readline().strip())

    result = max_turtle_distance(commands, n)
    print(result)
