import sys

def find(parent, x):
    while parent[x] != x:
        parent[x] = parent[parent[x]]  # Path compression
        x = parent[x]
    return x

def union(parent, rank, x, y):
    px = find(parent, x)
    py = find(parent, y)
    if px == py:
        return
    if rank[px] < rank[py]:
        parent[px] = py
    elif rank[px] > rank[py]:
        parent[py] = px
    else:
        parent[py] = px
        rank[px] += 1

def solve() -> None:
    data = sys.stdin.buffer.read().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    q = int(next(it))

    a = []
    for _ in range(n):
        a.append(int(next(it)))

    parent = [i for i in range(n + 1)]  # 1-indexed
    rank = [1] * (n + 1)

    # Process each bit (0 to 20)
    for bit in range(21):
        indices = []
        for i in range(n):
            if a[i] & (1 << bit):
                indices.append(i + 1)  # Convert to 1-indexed

        if len(indices) <= 1:
            continue

        # Connect all consecutive indices in this bit group
        for i in range(len(indices) - 1):
            x = indices[i]
            y = indices[i + 1]
            union(parent, rank, x, y)

    # Process queries
    out_lines = []
