def count_covered_cells(horizontal_segments, vertical_segments):
    # Track the range of x covered by each horizontal line
    h_lines = {}
    for y, y1, y2, x_start, x_end in horizontal_segments:
        if y not in h_lines:
            h_lines[y] = [x_start, x_end]
        else:
            h_lines[y][0] = min(h_lines[y][0], x_start)
            h_lines[y][1] = max(h_lines[y][1], x_end)

    # Track the range of y covered by each vertical line
    v_lines = {}
    for x, x1, x2, y_start, y_end in vertical_segments:
        if x not in v_lines:
            v_lines[x] = [y_start, y_end]
        else:
            v_lines[x][0] = min(v_lines[x][0], y_start)
            v_lines[x][1] = max(v_lines[x][1], y_end)

    # Calculate total covered by horizontal segments
    total_horizontal = 0
    for y in h_lines:
        x_start, x_end = h_lines[y]
        total_horizontal += x_end - x_start + 1

    # Calculate total covered by vertical segments
    total_vertical = 0
    for x in v_lines:
        y_start, y_end = v_lines[x]
        total_vertical += y_end - y_start + 1

    # Calculate intersection cells
    intersect = 0
    for y in h_lines:
        x_start, x_end = h_lines[y]
        for x in v_lines:
            y_start, y_end = v_lines[x]
            # Check if they intersect
            if x_start <= x <= x_end and y_start <= y <= y_end:
                intersect += 1

    return total_horizontal + total_vertical - intersect

