def solve():
    n = int(input())
    tree = [[] for _ in range(n)]
    parent = [0] * n
    children = [[] for _ in range(n)]
    c = [0] * n

    for i in range(n):
        p_i, c_i = map(int, input().split())
        parent[i] = p_i - 1  # Convert to 0-indexed
        c[i] = c_i
        if p_i != 0:
            children[p_i - 1].append(i)

    # Assign values from 1 to n
    a = [0] * n

    # Post-order traversal to process children first
    def dfs(node):
        # Collect values from all children
        subtree_values = []
        for child in children[node]:
            dfs(child)
            subtree_values.extend(a[child:])  # Collect all values from subtree

        # Now assign value to this node
        # We need exactly c[node] values in subtree to be smaller than a[node]

        if not subtree_values:
            # Leaf node
            if c[node] == 0:
                a[node] = 1
            else:
                return False
        else:
            # Sort values
            subtree_values.sort()

            # Find where to place a[node]
            if c[node] == 0:
                a[node] = subtree_values[0] + 1
            elif c[node] == len(subtree_values):
                a[node] = subtree_values[-1] + 1
            else:
                a[node] = subtree_values[c[node]] + 1

        return True

    if dfs(0):  # Start from root (node 0)
        print("YES")
        print(' '.join(map(str, a)))
    else:
        print("NO")

solve()
