from typing import Tuple

def read_input():
    """Read input from stdin"""
    data = input().strip().split()
    coords = list(map(int, data))
    return coords

def get_square_vertices(coords: list) -> list:
    """Get the vertices of a square from its coordinates"""
    vertices = []
    for i in range(0, 8, 2):
        x, y = coords[i], coords[i+1]
        vertices.append((x, y))
    return vertices

# Helper function for barycentric coordinates
# https://stackoverflow.com/a/14793934/7052716
def barycentric(p, a, b, c) -> Tuple[float, float, float]:
    d = (b[0] - a[0]) * (c[1] - a[1]) - (b[1] - a[1]) * (c[0] - a[0])
    if abs(d) < 1e-10:
        return (0, 0, 0)  # colinear
    d1 = (c[0] - b[0]) * (a[1] - b[1]) - (c[1] - b[1]) * (a[0] - b[0])
    d2 = (a[0] - c[0]) * (b[1] - c[1]) - (a[1] - c[1]) * (b[0] - c[0])
    return (d1 / d, d2 / d, 1 - d1 / d - d2 / d)

# Check if point p is inside triangle abc (barycentric coordinates)
def point_in_triangle(p, a, b, c):
    bary = barycentric(p, a, b, c)
    return bary[0] >= -1e-10 and bary[1] >= -1e-10 and bary[2] >= -1e-10

# Check if point p is inside a polygon (rotated or axis-aligned square)
def point_in_polygon(p, polygon):
    # For axis-aligned square
    if len(polygon) == 4:
        x, y = p
        x_min = min(v[0] for v in polygon)
        x_max = max(v[0] for v in polygon)
        y_min = min(v[1] for v in polygon)
        y_max = max(v[1] for v in polygon)

        # Check if point is inside the bounding box
        if not (x_min <= x <= x_max and y_min <= y <= y_max):
            return False

        # Now check if the point is inside the polygon
        # For axis-aligned square, we can use the simple bounding box
        return True

    # For rotated square (check if point is within the polygon)
    for i in range(len(polygon)):
        a, b = polygon[i], polygon[(i+1)%len(polygon)]
        if (a[1] - b[1]) * (p[0] - a[0]) != (a[0] - b[0]) * (p[1] - a[1]):
            # Point is on the edge or outside
            return False
    return True

# Check if line segment ab intersects line segment cd
# https://stackoverflow.com/a/56319880/7052716
def segments_intersect(a, b, c, d):
    # Check if line segment ab intersects with line segment cd
    def ccw(p, q, r):
        return (q[0] - p[0]) * (r[1] - p[1]) - (q[1] - p[1]) * (r[0] - p[0])

    ccw1 = ccw(a, b, c)
    ccw2 = ccw(a, b, d)
    ccw3 = ccw(c, d, a)
    ccw4 = ccw(c, d, b)

    if (ccw1 * ccw2 < 0) and (ccw3 * ccw4 < 0):
        return True

    # Check if endpoints lie on the other segment
    if abs(ccw1) < 1e-10 and abs(ccw2) < 1e-10:
        return False
    if abs(ccw3) < 1e-10 and abs(ccw4) < 1e-10:
        return False

    return False

# Check if any vertex of square1 is inside square2
def vertices_inside(s1, s2):
    for v in s1:
        if point_in_polygon(v, s2):
            return True
    return False

# Check if any edge of square1 intersects any edge of square2
def edges_intersect(s1, s2):
    for i in range(len(s1)):
        for j in range(len(s2)):
            if segments_intersect(s1[i], s1[(i+1)%len(s1)], s2[j], s2[(j+1)%len(s2)]):
                return True
    return False

