import sys

def comb2(x):
    """Calculate C(x, 2) = x * (x-1) // 2"""
    return x * (x - 1) // 2

def solve_one_case(n, k):
    """Find the k-th string for given n and k"""
    result = []

    for i in range(1, n + 1):
        # How many ways if we place 'a' at position i
        remaining_positions = n - i
        ways_with_a = comb2(remaining_positions)

        if k > ways_with_a:
            # Place 'b' at this position
            result.append('b')
            k -= ways_with_a
        else:
            # Place 'a' at this position
            result.append('a')

    return ''.join(result)

def main():
    data = sys.stdin.read().strip().split()
    if not data:
