def solve():
    n = int(input())
    positions = []
    for _ in range(n - 1):
        x, y = map(int, input().split())
        positions.append((x, y))

    # For each column, find the minimum row that contains a 1
    col_min_row = [n + 1] * (n + 1)  # col_min_row[y] = min row with 1 in column y
    for x, y in positions:
        col_min_row[y] = min(col_min_row[y], x)

    # We need to assign each column to a new position π(y) such that π(y) < col_min_row[y]
    # And we need π to be a permutation of {1, 2, ..., n}

    # One approach: greedily assign columns to positions
    used_positions = [False] * (n + 1)

    # For each column from 1 to n:
    #   if it has a 1, assign it to a position < col_min_row[y]
    #   if it doesn't have a 1, assign it to an empty position

    moves = []

    for y in range(1, n + 1):
        if col_min_row[y] == n + 1:
            # This column has no 1s, assign it to the first available position
            for pos in range(1, n + 1):
                if not used_positions[pos]:
                    moves.append((2, y, pos))  # swap column y with position pos
                    used_positions[pos] = True
                    break
        else:
            # This column has a 1, assign it to a position < col_min_row[y]
            target_pos = col_min_row[y] - 1  # The largest position < col_min_row[y]
            if not used_positions[target_pos]:
                moves.append((2, y, target_pos))  # swap column y with target position
                used_positions[target_pos] = True
            else:
                # Need to find another position
                for pos in range(1, target_pos):
                    if not used_positions[pos]:
                        moves.append((2, y, pos))
                        used_positions[pos] = True
                        break

    print(len(moves))
    for move in moves:
        print(move)

