import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    q = int(data[1])

    res = []
    idx = 2

    for _ in range(q):
        u = int(data[idx])
        idx += 1
        path = data[idx]
        idx += 1

        # Simulate the tree
        height = 0
        while (1 << (height + 1)) - 1 <= n:
            height += 1
        root = 1 << height

        # Find parent of a vertex
        def get_parent(v):
            if v == root:
                return 0
            if v < root:
                return 2 * v
            return 2 * v - 1

        # Find left child
        def get_left(v):
            if v == root:
                return 0
            if v < root:
                return 2 * v
            return 2 * v - 1

        # Find right child
        def get_right(v):
            if v == root:
                return 0
            if v < root:
                return 2 * v - (1 << (height - 1)) + 1
            return 2 * v + (1 << (height - 1)) - 1

        result = u
        for c in path:
            if c == 'U':
                parent = get_parent(result)
                if parent >= 1:
                    result = parent
            elif c == 'L':
                left = get_left(result)
                if left <= n:
                    result = left
            elif c == 'R':
                right = get_right(result)
                if right <= n:
                    result = right

        res.append(str(result))

    sys.stdout.write("\n".join(res))

if __name__ == "__main__":
    solve()
