            a.append(ai)
            b.append(bi)

        # dp[i][h] = minimum cost to make first i boards great, with i-th board height h
        # We'll track for each position and each possible height (but we need to be efficient)

        # For position 0, we can just increase it to any height h >= a[0]
        # The cost to reach height h is (h - a[0]) * b[0]
        dp_prev = {}

        # For the first board, consider heights up to a[0] + some limit
        # We only need to consider heights up to a[0] + n, because we can't have more than n boards
        max_h = a[0] + 1000  # We'll use a limit to keep it finite

        for h in range(a[0], max_h + 1):
            dp_prev[h] = (h - a[0]) * b[0]

        # For each subsequent board
        for i in range(1, n):
            dp_curr = {}

            # Consider all possible heights for current board
            # We need to ensure the current height is different from previous height

            for curr_h in range(a[i], max_h + 1):
                # Find minimum cost from dp_prev where prev_h != curr_h
                min_cost = float('inf')

                for prev_h in dp_prev:
                    if prev_h != curr_h:
                        min_cost = min(min_cost, dp_prev[prev_h])

                if min_cost != float('inf'):
                    dp_curr[curr_h] = min_cost + (curr_h - a[i]) * b[i]

        # The answer is the minimum cost among all possible heights for the last board
        print(min(dp_curr.values()))

