    for i in range(n):
        row = data[idx:idx+m]
        matrix.append([int(cell) for cell in row])
        idx += m

    # Check if it's possible to make the matrix good
    # A matrix is good if every even-length square has odd sum
    # After thinking, I realize the condition is:
    # For a matrix to be good, every cell (i, j) must be equal to its top-left neighbor (1, 1)
    # if and only if both (i-1) and (j-1) are even.

    # Check this condition
    val = matrix[0][0]
    for i in range(n):
        for j in range(m):
            if (i - 1) % 2 == 0 and (j - 1) % 2 == 0:
                if matrix[i][j] != val:
                    return -1
            else:
                if matrix[i][j] == val:
                    return -1

    # If we passed the check, calculate the minimum changes
    changes = 0
    for i in range(n):
        for j in range(m):
            if (i - 1) % 2 == 0 and (j - 1) % 2 == 0:
                if matrix[i][j] != val:
                    changes += 1

    print(changes)

