    # After reconsidering, I think the condition is that:
    # For a matrix to be good, every 2x2 sub-matrix must have an odd sum.
    # This means we need a checkerboard pattern where adjacent cells have different values.

    # Check if a checkerboard pattern is possible
    # We can have two patterns: starting with 0 or starting with 1
    # Let's check both

    # Pattern 1: (i+j) % 2 == 0 -> value = v, else value = 1-v
    # Pattern 2: (i+j) % 2 == 0 -> value = 1-v, else value = v

    # Check pattern 1
    v1 = matrix[0][0]
    good1 = True
    for i in range(n):
        for j in range(m):
            expected = v1 if (i + j) % 2 == 0 else 1 - v1
            if matrix[i][j] != expected:
                good1 = False
                break
        if not good1:
            break

    # Check pattern 2
    v2 = matrix[0][0]
    good2 = True
    for i in range(n):
        for j in range(m):
            expected = v2 if (i + j) % 2 == 0 else 1 - v2
            if matrix[i][j] != expected:
                good2 = False
                break
        if not good2:
            break

    if not good1 and not good2:
        print(-1)
        return

    # Calculate minimum changes
    if good1:
        changes1 = 0
        for i in range(n):
            for j in range(m):
                expected = matrix[0][0] if (i + j) % 2 == 0 else 1 - matrix[0][0]
                if matrix[i][j] != expected:
