def time_to_seconds(time_str):
    """Convert hh:mm:ss string to number of seconds since midnight"""
    hh, mm, ss = map(int, time_str.split(':'))
    return hh * 3600 + mm * 60 + ss

n, M, T = map(int, input().split())
queries = [input().strip() for _ in range(n)]

# Convert to seconds
times = [time_to_seconds(q) for q in queries]

# We want to maximize the number of distinct users
# Try greedy assignment by grouping consecutive queries
# that are within T-1 seconds
user_id = 1
results = [0] * n

for i in range(n):
    if i == 0:
        results[i] = user_id
        user_id += 1
    else:
        # Try to reuse the same user as the previous query
        if times[i] - times[i-1] <= T - 1:
            results[i] = results[i-1]
        else:
            results[i] = user_id
            user_id += 1

# Verify constraints
online = {}
max_users = 0

for idx, time in enumerate(times):
    user = results[idx]
    end = time + T - 1

    # Add the start of the interval
    if time in online:
        online[time] += 1
    else:
        online[time] = 1
    max_users = max(max_users, online[time])

    # Remove the end of the interval
    if end + 1 in online:
        online[end + 1] -= 1
        if online[end + 1] == 0:
            del online[end + 1]

if max_users == M:
    print(len(set(results)))
    for result in results:
        print(result)
else:
    print("No solution")
