def find_path_cost(a, b, costs):
    """Find the total cost of the shortest path from a to b"""
    cost = 0

    # Move a and b up to the lowest common ancestor
    while a != b:
        # Move the larger node up
        if a > b:
            a //= 2
        else:
            b //= 2

        # Add the cost of the edge we took
        cost += costs[(a * 2, a)] if a * 2 == b else costs[(b * 2, b)]

    return cost

def solve():
    q = int(input())

    # costs will store the cost of each edge
    # Key format: (child, parent) or (parent, child) - we'll store both
    costs = {}

    for _ in range(q):
        parts = input().split()
        if parts[0] == '1':  # Update event
            v, u, w = int(parts[1]), int(parts[2]), int(parts[3])

            # Find path from v to u and update costs
            a, b = v, u
            while a != b:
                if a > b:
                    a //= 2
                else:
                    b //= 2

                # Add w to both directions of the edge
                edge = (a * 2, a) if a * 2 == b else (b * 2, b)
                if edge in costs:
                    costs[edge] += w
                else:
                    costs[edge] = w
        else:  # Query event
            v, u = int(parts[1]), int(parts[2])
            a, b = v, u
            total_cost = 0

            # Find path from v to u and accumulate costs
            while a != b:
                if a > b:
                    a //= 2
                else:
                    b //= 2

                # Add cost of the edge
                edge = (a * 2, a) if a * 2 == b else (b * 2, b)
                total_cost += costs.get(edge, 0)

            print(total_cost)

solve()
