import sys

def solve():
    # Read input
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    ratings = list(map(int, data[1:1+n]))

    # Find the minimum rating
    min_rating = min(ratings)

    # We want to make all ratings equal, starting from the highest rating
    while True:
        # Check if all ratings are equal
        if all(r == ratings[0] for r in ratings):
            break

        # Find the first friend with rating greater than the minimum
        for i in range(n):
            if ratings[i] > min_rating:
                max_friend = i
                break

        # Find at least one other friend to form a party
        party = [max_friend]
        for j in range(n):
            if j != max_friend:
                party.append(j)
                if len(party) >= 2:
                    break

        # Decrease all members of the party
        for k in party:
            ratings[k] -= 1

        # Update min_rating
        min_rating = min(ratings)

    # Output the results
    print(min_rating)
    print(len(party) if party else 0)
    for _ in range(len(party)):
        print(''.join(['1' if i in party else '0' for i in range(n)]))

if __name__ == '__main__':
    solve()
