from collections import Counter

# Create orbits
def create_orbits(n):
    orbits = []

    # For each cell (i, j)
    for i in range(n):
        for j in range(n):
            # Find representative of the orbit
            representative = (i, j)

            # Check if we've already seen this orbit
            if representative in orbits:
                continue

            # Create a new orbit
            orbit = []
            for orbit_i in range(n):
                for orbit_j in range(n):
                    if (orbit_i, orbit_j) == (i, j):
                        # Check if this is the representative
                        if i == orbit_i and j == orbit_j:
                            orbit.append(orbit_i, orbit_j)
                        continue

                    # Check if (orbit_i, orbit_j) is in the same orbit
                    if orbit_i == n-1-i and orbit_j == j:
                        orbit.append(orbit_i, orbit_j)
                    elif orbit_i == i and orbit_j == n-1-j:
                        orbit.append(orbit_i, orbit_j)
                    elif orbit_i == n-1-i and orbit_j == n-1-j:
                        orbit.append(orbit_i, orbit_j)
            orbits.append(orbit)
    return orbits

