def solve(n, numbers):
    if n == 1:
        if len(numbers) == 1:
            return "YES", [numbers[0]]
        else:
            return "NO", []

    # Count frequency of each number
    freq = Counter(numbers)

    # Create orbits
    orbits = create_orbits(n)

    # For each orbit, we need to count how many numbers it needs
    orbit_counts = [0] * len(orbits)
    for i, orbit in enumerate(orbits):
        count = 1
        if i == len(orbits) - 1:
            # This is the center orbit
            count = 1
        elif i == len(orbits) - 2:
            # This is the middle row/column orbit
            count = 2
        else:
            # This is a regular orbit
            count = 4
        orbit_counts[i] = count

    # Check if we can distribute numbers
    for orbit in range(len(orbits)):
        orbit_size = orbit_counts[orbit]
        if freq[orbit] != orbit_size:
