def is_palindromic(n, matrix):
    # Check if the matrix is palindromic
    # Row symmetry: reverse rows and check
    for i in range(n // 2):
        if matrix[i] != matrix[n-1-i]:
            return False

    # Column symmetry: reverse columns and check
    for j in range(n // 2):
        for i in range(n):
            if matrix[i][j] != matrix[i][n-1-j]:
                return False
    return True

