                        if new_digit == int(new_pin[i]):
                            continue  # Skip if digit is unchanged
                        new_pin[i] = str(new_digit)

                new_pin_str = ''.join(new_pin)

                # Check if this new pin is unique
                if new_pin_str not in used:
                    used.add(new_pin_str)

                    # Recursively process next pin
                    result_changes, result_used = backtrack(index + 1, used, changes + 1)

                    if result_changes is not None:
