def move_up(v, root):
    """Return the parent of vertex v, or None if v is root"""
    if v == root:
        return None
    if v % 2 == 0:
        # v is even, parent is v / 2
        return v // 2
    else:
        # v is odd, parent is (v - 1) / 2
        return (v - 1) // 2

def move_down(v, root):
    """Return the left child of vertex v, or None if v is a leaf"""
    if v >= root:
        # v is in right half, its left child is v - (root / 2)
        return v - (root // 2)
    else:
        # v is in left half, its left child is v * 2
        return v * 2

