def build_tree(n):
    """Build the tree structure for n = 2^k - 1 using symmetric numbering"""
    # We'll store left and right children for each node
    left_child = [0] * (n + 2)
    right_child = [0] * (n + 2)
    parent = [0] * (n + 2)

    # n+1 is a power of 2, so n = 2^k - 1 for some k
    # root = 2^(k-1)
    k = n.bit_length()
    root = 1 << (k - 1)

    # Build the tree recursively
    def build(start, end, node):
        if start > end:
            return
        # Root of this subtree
        if start <= end:
            root = (start + end) // 2
            # Left child of root
            if start <= root - 1:
                build(start, root - 1, 2*root)
            # Right child of root
            if root + 1 <= end:
                build(root + 1, end, 2*root+1)
            # Record parent, left child, right child
            parent[root] = node
            if 2*root <= end:
                left_child[root] = 2*root
            if 2*root+1 <= end:
                right_child[root] = 2*root+1

    build(1, n, root)

    return parent, left_child, right_child

