import sys

def solve():
    input = sys.stdin.read().strip().split()
    data = list(map(int, input))
    idx = 0

    T = data[idx]
    idx += 1

    results = []

    for _ in range(T):
        n, k = data[idx], data[idx + 1]
        idx += 2
        a = data[idx:idx + n]
        idx += n

        used_powers = set()
        can_construct = True

        for val in a:
            if val == 0:
                continue

            power = 0
            while val > 0:
                power_val = k ** power
                if power_val > val:
                    break
                if power_val in used_powers:
                    can_construct = False
                    break
                used_powers.add(power_val)
                val -= power_val
                power += 1
            if not can_construct:
                break

        if can_construct:
            results.append("YES")
        else:
            results.append("NO")

    sys.stdout.write("\n".join(results))

if __name__ == "__main__":
    solve()
