from collections import deque

def bfs(grid, n, m, source, target):
    """BFS to check if there's a path from source to target"""
    visited = [[False] * m for _ in range(n)]
    queue = deque([source])
    visited[source[0]][source[1]] = True

    while queue:
        r, c = queue.popleft()
        if (r, c) == target:
            return True

        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < n and 0 <= nc < m and grid[nr][nc] == '#' and not visited[nr][nc]:
                visited[nr][nc] = True
                queue.append((nr, nc))

    return False

def min_vertex_cut(grid, n, m, source, target):
    """Find minimum vertex cut between source and target using BFS"""
    if source == target:
        return 0

    # BFS to find minimum vertex cut
    visited = [[False] * m for _ in range(n)]
    queue = deque([source])
    visited[source[0]][source[1]] = True
    parent = {}

    while queue:
        r, c = queue.popleft()

        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < n and 0 <= nc < m and grid[nr][nc] == '#':
                if (nr, nc) == target:
                    # Found target, reconstruct path
                    path = []
                    node = target
                    while node != source:
                        path.append(node)
                        node = parent[node]
                    path.append(source)
                    path.reverse()
                    return len(path) - 1  # Min vertex cut = min number of squares to delete

                if not visited[nr][nc]:
                    visited[nr][nc] = True
                    parent[(nr, nc)] = (r, c)
                    queue.append((nr, nc))

    return -1  # No path found

