def is_connected(grid, n, m):
    """Check if all painted squares are connected"""
    painted = [(i, j) for i in range(n) for j in range(m) if grid[i][j] == '#']
    if len(painted) <= 1:
        return True

    # For each square, check if it can reach all other painted squares
    for start in painted:
        visited = set([start])
        queue = [start]
        while queue:
            i, j = queue.pop(0)
            for ni, nj in [(i-1,j), (i+1,j), (i,j-1), (i,j+1)]:
                if 0 <= ni < n and 0 <= nj < m:
                    if (ni, nj) == start:
                        continue
                    if grid[ni][nj] == '#' and (ni, nj) not in visited:
                        visited.add((ni, nj))
                        queue.append((ni, nj))
        if len(visited) < len(painted):
            return False
    return True

