            for ni, nj in [(i-1,j), (i+1,j), (i,j-1), (i,j+1)]:
                if 0 <= ni < n and 0 <= nj < m:
                    if (ni, nj) == start:
                        continue
                    if grid[ni][nj] == '#' and (ni, nj) not in visited:
                        visited.add((ni, nj))
                        queue.append((ni, nj))
        if len(visited) < len(painted):
            return False
    return True

n, m = map(int, input().split())
grid = []
for _ in range(n):
    grid.append(list(input().strip()))

# Check if the set is connected (should be true)
# If not connected already, output -1
if not is_connected(grid, n, m):
    print(-1)
else:
    # Try removing one square
    answer = -1
    for i in range(n):
