                # Create a copy
                temp_grid = [row[:] for row in grid]
                temp_grid[i][j] = '.'

                # Check if it's not connected
                if not is_connected(temp_grid, n, m):
                    answer = 1
                    break
        if answer != -1:
            break

    if answer == -1:
